        editDelegate.setEditMode(editMode);
      } catch (final Exception e) {
        e.printStackTrace();
        // toggle back to previous state since setEditMode failed
        m_ui.getEditModeButtonModel().setSelected(!m_ui.getEditModeButtonModel().isSelected());
      }
    }
  };

