    final GameData data = getGameData();
    if (!getPlayerID().amNotDeadYet(data) || getPlayerBridge().isGameOver()) {
      return true;
    }
    return m_ui.acceptAction(playerSendingProposal, "To " + getPlayerID().getName() + ": " + acceptanceQuestion,
